$ab = list_random( [3, 4], [6, 8], [5, 12], [9, 12], [8, 15], [12, 16], [15, 20], [7, 24], [10, 24], [20, 21], [18, 24], [16, 30], [21, 28] ); ($a, $b) = @$ab; $c = Real(sqrt($a**2 + $b**2)); $p = $a + $b + $c; Context()->variables->are(b => 'Real'); $proposed_solution = (random(0,1)) ? $b : $b + non_zero_random(-1, 1); Context()->flags->set(reduceConstants => 0); $left = Formula("$a + b + sqrt($a^2 + b^2)"); $right = Formula("$p"); Context("LimitedNumeric"); $lefteval = Real($left->eval(b => $proposed_solution)); $righteval = Real($right->eval(b => $proposed_solution)); $dropdown = DropDown( ["Yes, it is a solution.", "No, it is not a solution."], ($lefteval == $righteval) ? 0 : 1, showInStatic => 0 );
